// Des: Tests for the state store
// Flo: temp db > counters, keys (crash = unsure), ledger, log, known targets
// I/O: scratch SQLite file > asserts (no leaks)
// Run: zig build test -Dfile=st-stat-main-test.zig
// ===================================================================
const std = @import("std"); const stat = @import("st-stat-main.zig");
const allo = std.testing.allocator;
fn dbPath(tmpz: *std.testing.TmpDir) ![:0]u8 { return std.fmt.allocPrintSentinel(allo, ".zig-cache/tmp/{s}/fb.db", .{tmpz.sub_path}, 0); }
test "caps counter counts only inside the window" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const pth = try dbPath(&tmpz); defer allo.free(pth); var sto = try stat.Stat.open(allo, pth); defer sto.close(); try sto.actAdd("post", "a", 100); try sto.actAdd("post", "b", 200); try sto.actAdd("comm", "c", 200); try std.testing.expectEqual(@as(i64, 2), try sto.actCnt("post", 0)); try std.testing.expectEqual(@as(i64, 1), try sto.actCnt("post", 150)); try std.testing.expectEqual(@as(i64, 1), try sto.actCnt("comm", 0)); }
test "key: first go, crash before done = unsure, done = dupe, drop reopens" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const pth = try dbPath(&tmpz); defer allo.free(pth); var sto = try stat.Stat.open(allo, pth); defer sto.close(); try std.testing.expectEqual(stat.Take.go, try sto.keyTake("k1", 1)); try std.testing.expectEqual(stat.Take.unsure, try sto.keyTake("k1", 2)); try sto.keyDone("k1", 3); try std.testing.expectEqual(stat.Take.dupe, try sto.keyTake("k1", 4)); try std.testing.expectEqual(stat.Take.go, try sto.keyTake("k2", 5)); try sto.keyDrop("k2"); try std.testing.expectEqual(stat.Take.go, try sto.keyTake("k2", 6)); }
test "state survives reopen (crash resume): pending key stays unsure" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const pth = try dbPath(&tmpz); defer allo.free(pth); { var sto = try stat.Stat.open(allo, pth); defer sto.close(); try std.testing.expectEqual(stat.Take.go, try sto.keyTake("job-1", 1)); } var sto = try stat.Stat.open(allo, pth); defer sto.close(); try std.testing.expectEqual(stat.Take.unsure, try sto.keyTake("job-1", 2)); }
test "ledger: add, mark sold once, list keeps exact title group time" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const pth = try dbPath(&tmpz); defer allo.free(pth); var sto = try stat.Stat.open(allo, pth); defer sto.close(); _ = try sto.ledgAdd("L1", "Red bike 26\"", "Bike Club HN", 1000); try std.testing.expectEqual(@as(i64, 1), try sto.ledgSet("Red bike 26\"", "sold", 2000)); try std.testing.expectEqual(@as(i64, 0), try sto.ledgSet("Red bike 26\"", "sold", 3000)); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const rows = try sto.ledgList(aren.allocator()); try std.testing.expectEqual(@as(usize, 1), rows.len); try std.testing.expectEqualStrings("Red bike 26\"", rows[0].titl); try std.testing.expectEqualStrings("Bike Club HN", rows[0].grou); try std.testing.expectEqual(@as(i64, 1000), rows[0].pms); try std.testing.expectEqualStrings("sold", rows[0].st); try std.testing.expectEqual(@as(i64, 2000), rows[0].ums); }
test "born is set once; flags and known targets persist" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const pth = try dbPath(&tmpz); defer allo.free(pth); var sto = try stat.Stat.open(allo, pth); defer sto.close(); try std.testing.expectEqual(@as(i64, 50), try sto.bornGet(50)); try std.testing.expectEqual(@as(i64, 50), try sto.bornGet(99)); try std.testing.expect(!try sto.flagGet("pause")); try sto.flagSet("pause", true); try std.testing.expect(try sto.flagGet("pause")); try sto.flagSet("pause", false); try std.testing.expect(!try sto.flagGet("pause")); try std.testing.expect(!try sto.knowHas("u1")); try sto.knowAdd("u1", 1); try sto.knowAdd("u1", 2); try std.testing.expect(try sto.knowHas("u1")); }
test "log returns newest first" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const pth = try dbPath(&tmpz); defer allo.free(pth); var sto = try stat.Stat.open(allo, pth); defer sto.close(); try sto.logAdd("post", "one", true, 1); try sto.logAdd("post", "two", false, 2); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const rows = try sto.logRecent(aren.allocator(), 5); try std.testing.expectEqual(@as(usize, 2), rows.len); try std.testing.expectEqualStrings("two", rows[0].what); try std.testing.expect(!rows[0].ok); }
test "ledger rows carry the id as a string too (row_id), the number stays for old readers" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const pth = try dbPath(&tmpz); defer allo.free(pth); var sto = try stat.Stat.open(allo, pth); defer sto.close(); _ = try sto.ledgAdd("L9", "Blue bike", "Club", 1000); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const rows = try sto.ledgList(aren.allocator()); try std.testing.expectEqual(@as(i64, 1), rows[0].id); try std.testing.expectEqualStrings("1", rows[0].row_id); const docz = try std.json.Stringify.valueAlloc(aren.allocator(), rows, .{}); try std.testing.expect(std.mem.find(u8, docz, "\"row_id\":\"1\"") != null); }
